import { Array, String, pipe } from 'effect';
import { OnCustomEvent, Prop, customElement as customElementVNode, } from '../html/index.js';
const kebabToPascal = (input) => pipe(input, String.split('-'), Array.map(String.capitalize), Array.join(''));
const IDENTIFIER_PATTERN = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const isValidPropertyName = (name) => IDENTIFIER_PATTERN.test(name);
const isValidEventName = (name) => {
    if (String.isEmpty(name)) {
        return false;
    }
    else {
        return pipe(name, String.split('-'), Array.every(segment => IDENTIFIER_PATTERN.test(segment)));
    }
};
const propertyFactoryName = (propertyName) => String.capitalize(propertyName);
const eventFactoryName = (eventName) => `On${kebabToPascal(eventName)}`;
/**
 * Define a typed binding for a custom element. The returned spec describes
 * the element's properties and events with Schema, and exposes a
 * `.withMessage<Message>()` factory that yields a typed `ElementBuilder` for
 * the consumer's Message universe.
 *
 * Property changes diff across renders; declared `CustomEvent`s are
 * converted to Messages by the runtime.
 *
 * @example
 * ```ts
 * // main.ts
 * import 'vanilla-colorful/hex-color-picker.js'
 * import { CustomElement } from 'foldkit'
 *
 * const hexColorPicker = CustomElement.define({
 *   tag: 'hex-color-picker',
 *   properties: {
 *     color: S.String,
 *   },
 *   events: {
 *     'color-changed': S.Struct({ value: S.String }),
 *   },
 * })
 *
 * const picker = hexColorPicker.withMessage<Message>()
 *
 * picker(
 *   [
 *     picker.Color(model.fillColor),
 *     picker.OnColorChanged(detail => ChangedFillColor({ value: detail.value })),
 *   ],
 *   [],
 * )
 * ```
 */
export const define = (config) => {
    const propertyNames = Object.keys(config.properties);
    const eventNames = Object.keys(config.events);
    validateNames({ tag: config.tag, propertyNames, eventNames });
    const buildForMessage = () => {
        const createVNode = customElementVNode()(config.tag);
        const elementFn = (attributes = [], children = []) => createVNode(attributes, children);
        /* eslint-disable-next-line @typescript-eslint/consistent-type-assertions */
        const builder = elementFn;
        for (const propertyName of propertyNames) {
            builder[propertyFactoryName(propertyName)] = (value) => Prop({ key: propertyName, value });
        }
        for (const eventName of eventNames) {
            builder[eventFactoryName(eventName)] = (toMessage) => OnCustomEvent({
                name: eventName,
                f: event => toMessage(event.detail),
            });
        }
        /* eslint-disable-next-line @typescript-eslint/consistent-type-assertions */
        return builder;
    };
    return {
        tag: config.tag,
        properties: config.properties,
        events: config.events,
        withMessage: buildForMessage,
    };
};
const validateNames = (input) => {
    const context = `CustomElement.define('${input.tag}')`;
    if (!input.tag.includes('-')) {
        throw new Error(`${context}: tag '${input.tag}' is not a valid custom element name. Autonomous custom elements must contain at least one hyphen (e.g. 'fk-emoji-rating').`);
    }
    for (const propertyName of input.propertyNames) {
        if (!isValidPropertyName(propertyName)) {
            throw new Error(`${context}: property name '${propertyName}' is not a valid JS identifier.`);
        }
    }
    for (const eventName of input.eventNames) {
        if (!isValidEventName(eventName)) {
            throw new Error(`${context}: event name '${eventName}' is not a valid kebab-case identifier. Expected lowercase segments separated by single hyphens.`);
        }
    }
    const factoryAssignments = new Map();
    const claim = (factoryName, source) => {
        const existing = factoryAssignments.get(factoryName);
        if (existing !== undefined) {
            throw new Error(`${context}: factory name '${factoryName}' is claimed by both ${existing} and ${source}.`);
        }
        factoryAssignments.set(factoryName, source);
    };
    for (const propertyName of input.propertyNames) {
        claim(propertyFactoryName(propertyName), `property '${propertyName}'`);
    }
    for (const eventName of input.eventNames) {
        claim(eventFactoryName(eventName), `event '${eventName}'`);
    }
};
